```python
def count_vowels(word):
    count = 0
    vowels = 'aeiouAEIOU'
    for char in word:
        if char in vowels:
            count += 1
    return count
```

```python
def invert_dict(d):
    inverted = {}
    for key, value in d.items():
        inverted[value] = key
    return inverted
```

```python
def linear_search(data_list, target):
    for index in range(len(data_list)):
        if data_list[index] == target:
            return index
    return -1
```

